fun <T> encode(value: T): ByteArray = CsilCbor.encode(csilToCborValue(value))

private fun csilToCborValue(value: Any?): CborValue = when (value) {
    null -> CborValue.CNull
    is BeginLoginRequest -> value.toCborValue()
    is BeginLoginResponse -> value.toCborValue()
    is PollLoginRequest -> value.toCborValue()
    is PollLoginResponse -> value.toCborValue()
    is WhoAmIRequest -> value.toCborValue()
    is WhoAmIResponse -> value.toCborValue()
    is IssueServiceTokenRequest -> value.toCborValue()
    is RefreshRequest -> value.toCborValue()
    is TokenResponse -> value.toCborValue()
    else -> throw CborError("no CSIL CBOR codec for ${value::class}")
}

/** Decode canonical CBOR bytes into a generated CSIL record of type [T]. */
inline fun <reified T> decode(bytes: ByteArray): T =
    csilFromCborValue(T::class, CsilCbor.decode(bytes)) as T

fun csilFromCborValue(type: kotlin.reflect.KClass<*>, cbor: CborValue): Any = when (type) {
    BeginLoginRequest::class -> beginLoginRequestFromCborValue(cbor)
    BeginLoginResponse::class -> beginLoginResponseFromCborValue(cbor)
    PollLoginRequest::class -> pollLoginRequestFromCborValue(cbor)
    PollLoginResponse::class -> pollLoginResponseFromCborValue(cbor)
    WhoAmIRequest::class -> whoAmIRequestFromCborValue(cbor)
    WhoAmIResponse::class -> whoAmIResponseFromCborValue(cbor)
    IssueServiceTokenRequest::class -> issueServiceTokenRequestFromCborValue(cbor)
    RefreshRequest::class -> refreshRequestFromCborValue(cbor)
    TokenResponse::class -> tokenResponseFromCborValue(cbor)
    else -> throw CborError("no CSIL CBOR codec for $type")
}
